import{z as B,x as A,o as t,c as d,q as n,j as l,D as r,d as e,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"内核与用户态","description":"","frontmatter":{"title":"内核与用户态","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-user.md","filePath":"cs/kernel-user.md","lastUpdated":1791413859000}'),p={name:"cs/kernel-user.md"};function m(c,a,D,h,u,C){const s=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="内核与用户态" tabindex="-1">内核与用户态 <a class="header-anchor" href="#内核与用户态" aria-label="Permalink to &quot;内核与用户态&quot;">​</a></h1><div class="epigraph"><p>操作系统是一直运行着的程序，它控制着应用程序，并充当计算机与应用程序之间的中介。</p><footer>—— 据 Silberschatz, Galvin and Gagne, Operating System Concepts 整理</footer></div><p><a href="/cs/bootstrapping">上一课</a>把编译课收到自举：用编译器编译自己，直到二进制稳定，信任链靠证明与测试一起撑住。<a href="/cs/privilege-rings">特权级</a>和<a href="/cs/exception-interrupt-entry">异常与中断入口</a>已经给出环与陷入；<a href="/cs/paging-vm">分页</a>和 <a href="/cs/tlb-translate">TLB</a>已经能把虚地址译成物理页。本课不重讲页表，也不重做 GC。缺口是：ISA 有环和陷阱，还没有命名<strong>哪一段程序拥有这台机器</strong>。操作系统课从这里开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户程序可以算、可以申请堆，但它不能直接改页表根、不能关中断、不能对磁盘端口乱写。若所有代码同一特权，一个越界存储就能毁掉调度器和文件系统。缺口不是再发明一套译址硬件，而是把软件切成两半：<strong>内核</strong>常驻高特权，<strong>用户态</strong>跑在低特权；越过边界只能走陷入。<span class="marginnote">可以想象成一栋宿舍楼：用户程序是住户，内核是握有总钥匙的物业。住户开自己房门（用自己的内存、算自己的数据）不用请示谁；要动水电气总闸（页表、磁盘、网卡），只能去前台填申请单。这张「申请单」就是后文的系统调用——权限不是靠自觉，而是硬件在每次访存和取指时都要查一遍。</span></p><p>本课只钉这道门。进程映像、系统调用路径、调度，都是后课在门的两侧展开的对象。</p><p><span class="marginnote">Tanenbaum 把内核定义为处理中断与陷入、操纵硬件的那一层。用户态看不到端口与页表；它看见的是后课才命名的系统调用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约定：复位后先进入内核，建立页表、中断向量、设备。此后用户程序以低特权运行；需要服务时执行陷入指令，硬件切到内核入口——入口约定沿用组成课，不重写。内核做完再返回用户 PC 与栈。<span class="marginnote">「陷入」（trap）翻译成大白话就是「CPU 的正规求助通道」：用户程序执行一条专用指令，硬件立刻把特权级抬高、跳到内核预先登记好的入口地址，办完事再把特权级降回来。它不是出错崩溃，而是用户态申请特权服务的唯一合法路径——自己写 <code>mov</code> 去改页表寄存器走不了这条路，只会被硬件拦下。</span></p>',9)),(t(),l(i,null,{default:r(()=>[o(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOT%5B%22%E5%A4%8D%E4%BD%8D%3A%20%E5%86%85%E6%A0%B8%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%20--%3E%20USER%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E6%89%A7%E8%A1%8C%22%5D%0A%20%20USER%20--%3E%20TRAP%5B%22%E9%99%B7%E5%85%A5%3A%20%E5%88%87%E9%AB%98%E7%89%B9%E6%9D%83%22%5D%0A%20%20TRAP%20--%3E%20KERN%5B%22%E5%86%85%E6%A0%B8%E5%A4%84%E7%90%86%22%5D%0A%20%20KERN%20--%3E%20RET%5B%22%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E6%80%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"内核映射通常对用户不可写；用户页对内核可见，这是后课系统调用拷贝参数的前提，本课只要求两边地址空间策略不同。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("有了内核/用户，错误被关在用户页里：缺页、非法指令、越权访问都进同一套入口，由内核决定杀进程还是补页。"),E("span",{class:"marginnote"},"初学者容易以为「程序出错崩溃」和「程序正常要服务」走的是两条路；实际上缺页、除零、主动申请内存都从同一个陷入入口进内核，差别只在内核查明原因后的裁决——是补一页让程序继续跑，还是记下信号直接终止它。入口统一意味着内核只需要维护一套检查逻辑。"),e("运行时的 GC 仍在用户堆上工作；它不能自己改 CR3。需要新物理页时，必须请内核。")],-1)),(t(),l(i,null,{default:r(()=>[o(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E4%BB%A3%E7%A0%81%E8%A6%81%E5%81%9A%E7%89%B9%E6%9D%83%E6%93%8D%E4%BD%9C%22%5D%20--%3E%20HW%5B%22%E7%A1%AC%E4%BB%B6%E6%9F%A5%E5%BD%93%E5%89%8D%E7%89%B9%E6%9D%83%E7%BA%A7%22%5D%0A%20%20HW%20--%3E%7C%E4%BD%8E%E7%89%B9%E6%9D%83%E8%B5%B0%E6%AD%A3%E8%A7%84%E9%80%9A%E9%81%93%7C%20T%5B%22%E9%99%B7%E5%85%A5%E5%86%85%E6%A0%B8%22%5D%0A%20%20T%20--%3E%20K%5B%22%E5%86%85%E6%A0%B8%E6%A0%B8%E6%9F%A5%E8%AF%B7%E6%B1%82%22%5D%0A%20%20K%20--%3E%7C%E5%90%88%E7%90%86%7C%20S%5B%22%E5%86%85%E6%A0%B8%E4%BB%A3%E4%B8%BA%E6%89%A7%E8%A1%8C%E5%B9%B6%E8%BF%94%E5%9B%9E%E7%BB%93%E6%9E%9C%22%5D%0A%20%20K%20--%3E%7C%E8%B6%8A%E6%9D%83%E6%88%96%E9%9D%9E%E6%B3%95%7C%20KILL%5B%22%E6%8B%92%E7%BB%9D%EF%BC%9A%E6%8A%A5%E9%94%99%E6%88%96%E7%BB%88%E6%AD%A2%E8%BF%9B%E7%A8%8B%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>内核不是「又一个运行时」。GC 管的是语言对象图；内核管的是 CPU、内存和设备的所有权。两者可以共存：托管语言的运行时是用户态程序，底下仍是这道特权门。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把微内核与宏内核的模块切分写完，也不列出 Linux 的 <code>syscall</code> 表。不重导页表项的有效位与权限位：那是分页课的对象，本课只使用「用户页不可执行特权指令」。也不把隔离当成安全课的沙箱；沙箱是更后的策略。</p><p>后课默认：谈到「谁在跑」，先问特权。用户程序默认没有设备与页表的写权限；要服务，就陷入——陷入的约定是下一课<a href="/cs/syscall-abi">系统调用 ABI</a>，被内核切换的那份<strong>进程映像</strong>再往后给。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ISA 已有环与陷入；本课命名内核为拥有机器的程序，用户态为被它中介的程序。</li><li>越过边界只能走陷入；GC 仍在用户堆上，不能改页表。</li><li>进程、系统调用、中断下半部都是后课缺口。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>Modern Operating Systems</em>。</li></ul>',6))])}const T=B(p,[["render",m]]);export{g as __pageData,T as default};
